-- Зимові поради агрокалендаря (грудень–лютий) для ягідників, садів і виноградників:
-- без них план на тиждень узимку майже порожній. Повторний запуск нічого не дублює.
insert into public.agro_calendar (crop_type, month, week_from, week_to, category, urgency, title, description)
select v.crop_type, v.month, v.week_from, v.week_to, v.category, v.urgency, v.title, v.description
from (values
  ('яблуня', 12, 1, 4, 'preparation', 'medium', 'Перевірка захисту штамбів', 'Після снігопадів і відлиг оглянути сітки та обв''язку на штамбах. Миші ходять під снігом, тому сніг навколо молодих дерев варто притоптати.'),
  ('яблуня', 12, 1, 4, 'disease', 'medium', 'Санітарна чистка саду', 'Зняти з дерев муміфіковані плоди й зимові гнізда золотогуза та глоду і знищити. У плодах зимує моніліоз, у гніздах — гусениці.'),
  ('груша', 12, 1, 4, 'disease', 'medium', 'Муміфіковані плоди та ракові рани', 'Зняти й знищити плоди, що лишилися на гілках. Позначити гілки з ознаками чорного раку чи цитоспорозу, щоб вирізати їх першими під час обрізки.'),
  ('черешня', 12, 1, 4, 'preparation', 'medium', 'Захист кори від сонячних опіків', 'Черешня найчутливіша до морозобоїн серед кісточкових. Якщо побілку змило дощами, у відлигу оновити її на штамбі й основі скелетних гілок.'),
  ('слива', 12, 1, 4, 'disease', 'medium', 'Знищення муміфікованих плодів', 'Зняти зі слив усохлі плоди («мумії») і зібрати їх з-під дерев. Це головне джерело моніліозу та кишеньок сливи наступного сезону.'),
  ('вишня', 12, 1, 4, 'disease', 'medium', 'Огляд на моніліальний опік', 'Зняти муміфіковані плоди. Засохлі торішні верхівки пагонів позначити — навесні їх вирізають на 10–15 см нижче межі ураження.'),
  ('лохина', 12, 1, 4, 'preparation', 'medium', 'Контроль укриття і снігу', 'Після відлиг і вітру перевірити агроволокно на молодих кущах. Сніг підгортати до основи кущів, а з гілок струшувати, щоб не ламав.'),
  ('лохина', 12, 2, 4, 'nutrition', 'low', 'Аналіз ґрунту на pH', 'У відлигу відібрати зразки ґрунту з рядів на глибині 0–20 см і здати в лабораторію. За результатом навесні розрахувати норму сірки.'),
  ('малина', 12, 1, 4, 'preparation', 'medium', 'Снігозатримання на пригнутих пагонах', 'Пригнуті пагони мають зимувати під снігом. На продуваних ділянках затримувати сніг щитами чи гілками, після відлиг перевірити, щоб пагони не вмерзли в лід.'),
  ('полуниця', 12, 1, 4, 'preparation', 'medium', 'Контроль укриття плантації', 'Шар снігу 10–15 см захищає полуницю до −20 °C. Якщо мороз без снігу — укрити агроволокном 60 г/м² або соломою.'),
  ('полуниця', 12, 1, 4, 'pest', 'medium', 'Гризуни під мульчею', 'Миші та полівки зимують під соломою й укриттям і об''їдають ріжки. Перевірити нори по краях плантації, за потреби розкласти принади в закритих контейнерах.'),
  ('смородина', 12, 1, 4, 'preparation', 'low', 'Снігозатримання біля кущів', 'Підгорнути сніг до основи кущів: він захищає кореневу шийку й бруньки відновлення від сильних морозів.'),
  ('аґрус', 12, 1, 4, 'disease', 'medium', 'Вирізка пагонів з борошнистою росою', 'Кінчики пагонів з бурим повстяним нальотом (американська борошниста роса) вирізати до здорової деревини й знищити — на них зимує гриб.'),
  ('ожина', 12, 1, 4, 'preparation', 'medium', 'Перевірка укриття пагонів', 'Після відлиг перевірити, чи пагони не підопріли під плівкою. Укриття має бути сухим, з продухами по краях.'),
  ('виноград', 12, 1, 4, 'preparation', 'high', 'Перевірка укриття лози', 'Для укривних сортів: рукави, присипані ґрунтом, не повинні оголитися після дощів. Під плівкою лишити продухи, щоб лоза не випріла.'),
  ('виноград', 12, 1, 3, 'preparation', 'medium', 'Заготівля чубуків', 'Нарізати здорові визрілі пагони завтовшки 7–10 мм на 3–4 вічка. Зберігати у вологому піску чи поліетилені при 0…+4 °C.'),
  ('яблуня', 1, 3, 4, 'preparation', 'high', 'Початок зимової обрізки', 'Дорослі дерева зимостійких сортів можна обрізати при температурі не нижче −8 °C. Молоді дерева й ніжні сорти — у березні. Зрізи понад 2 см замазати.'),
  ('яблуня', 1, 1, 4, 'pest', 'medium', 'Огляд на зимуючих шкідників', 'На однорічних пагонах шукати кладки попелиці й медяниці, на корі — щитівку. Від кількості залежить, чи потрібне ранньовесняне обприскування олійним препаратом.'),
  ('груша', 1, 1, 4, 'pest', 'medium', 'Огляд на медяницю і щитівку', 'Біля бруньок шукати яйця медяниці, на корі — щитівку. При сильному заселенні запланувати обприскування олійним препаратом до розпускання бруньок.'),
  ('черешня', 1, 1, 4, 'preparation', 'medium', 'Перевірка квіткових бруньок після морозів', 'Після морозів нижче −25 °C зрізати кілька гілок і розрізати бруньки: побурілий центр означає загибель. Від частки живих бруньок залежить обрізка й прогноз урожаю.'),
  ('слива', 1, 1, 4, 'preparation', 'medium', 'Оцінка підмерзання', 'Після сильних морозів поставити зрізані гілки у воду в теплі на 7–10 днів. Бруньки, що не розпустилися, загинули — це враховують при обрізці.'),
  ('вишня', 1, 1, 4, 'pest', 'low', 'Гнізда шкідників і кладки', 'Зняти павутинні гнізда й кільчасті кладки шовкопряда на гілках. Перевірити штамби на щитівку.'),
  ('лохина', 1, 1, 4, 'preparation', 'medium', 'Огляд кущів після морозів', 'У відлигу оглянути гілки: тріщини кори й почорнілі верхівки позначити для весняної обрізки. Перевірити, чи не пошкодили кущі зайці.'),
  ('малина', 1, 1, 4, 'pest', 'medium', 'Огляд пагонів на галиці й плямистості', 'Пагони з потовщеннями (стеблова галиця) та бурувато-фіолетовими плямами (дидимела) позначити — навесні їх вирізають і знищують першими.'),
  ('полуниця', 1, 1, 4, 'preparation', 'medium', 'Захист від випрівання', 'У тривалі відлиги під плівкою чи щільним шаром мульчі серце куща може випріти. Плівку на теплий період знімати, мульчу розпушити.'),
  ('смородина', 1, 3, 4, 'pest', 'high', 'Нирковий кліщ', 'Округлі роздуті бруньки («капустинки») — ознака ниркового кліща. Вищипати й знищити, сильно уражені гілки вирізати до основи.'),
  ('аґрус', 1, 1, 4, 'pest', 'low', 'Огляд на щитівку і склівку', 'Перевірити старі гілки на щитівку, а пагони — на всохлі ділянки з ходами склівки всередині. Уражені гілки вирізати до здорової серцевини.'),
  ('ожина', 1, 1, 4, 'preparation', 'low', 'Захист від гризунів', 'Під укриттям пагони можуть об''їдати миші. Оглянути основу кущів, за потреби розкласти принади в закритих контейнерах.'),
  ('виноград', 1, 1, 4, 'preparation', 'high', 'Перевірка вічок на підмерзання', 'Зрізати 10–20 пагонів з різних кущів і розрізати вічка: зелений центр — живе, коричневий — загинуло. Якщо загинуло понад 30%, при обрізці лишають більше вічок.'),
  ('яблуня', 2, 1, 4, 'preparation', 'high', 'Обрізка зимостійких сортів', 'Продовжувати обрізку при температурі вище −8 °C, спочатку старі дерева. Гілки з чорним раком і цитоспорозом вирізати до здорової деревини й спалити.'),
  ('яблуня', 2, 3, 4, 'pest', 'medium', 'Очищення кори на старих деревах', 'Зчистити відмерлу кору на штамбах і скелетних гілках — під нею зимують гусениці плодожерки. Рани зачистити й замазати садовим варом.'),
  ('лохина', 2, 2, 4, 'irrigation', 'medium', 'Підготовка крапельного поливу', 'Перевірити магістраль і крапельні лінії, промити фільтри, налаштувати дозатор кислоти. До початку сезону замінити пошкоджені ділянки.'),
  ('малина', 2, 3, 4, 'preparation', 'medium', 'Ремонт шпалери', 'Замінити хиткі стовпи, натягнути провислий дріт. Шпалеру треба полагодити до того, як навесні піднімуть і підв''яжуть пагони.'),
  ('виноград', 2, 3, 4, 'preparation', 'high', 'Обрізка неукривних сортів', 'Наприкінці лютого, при температурі вище −5 °C і до початку сокоруху, обрізати неукривні сорти. Навантаження вічками — з поправкою на зимову перевірку.'),
  ('виноград', 2, 1, 4, 'preparation', 'medium', 'Ремонт шпалери', 'Перевірити стовпи й дріт, замінити зламані кілки. Після відкриття укривних кущів часу на це вже не буде.'),
  ('вишня', 2, 2, 4, 'preparation', 'high', 'Обрізка в кінці зими', 'Проріджувальна й санітарна обрізка до набрякання бруньок. Засохлі від моніліозу верхівки вирізати на 10–15 см нижче межі ураження. Зрізи замазати.')
) as v(crop_type, month, week_from, week_to, category, urgency, title, description)
where not exists (
  select 1 from public.agro_calendar a
  where a.crop_type = v.crop_type and a.month = v.month and a.title = v.title
);
